(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.25)*18, w2 = Math.cos(y*0.022-t*0.3)*12;
  const w3 = Math.sin((x+y)*0.012+t*0.4)*10, w4 = Math.cos((x-y)*0.015-t*0.35)*8;
  const wx = w1+w2+w3, wy = w2+w3+w4;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp)*w;
    const harm=Math.sin(d*f*0.618-t*sp*0.382+0.5)*w*0.5;
    aS+=wave; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.414-t*sp*0.707+2.1)*w*0.3+harm;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15
    +Math.sin(sx*0.017+sy*0.031-t*0.6)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35
    +Math.sin(dist*0.03-ang*5+t*0.9)*0.15;
  const fib=dist*0.04-ang*2.39996+t*0.7;
  const fibW=Math.sin(fib)*Math.sin(fib*1.618)*0.2;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((cross*0.6-inh*0.4+bg*0.2+fibW)*1.8);
  const coupled=Math.tanh((rd1*0.7+rd2*0.5+Math.sin(rd1*rd2*3)*0.3)*1.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const voronoi=()=>{
    let md=999,m2=999;
    for(let i=0;i<8;i++){
      const vx=src[i][0]+Math.sin(t*0.3+i*1.7)*30, vy=src[i][1]+Math.cos(t*0.4+i*2.1)*25;
      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){m2=md;md=d;}else if(d<m2){m2=d;}
    }
    return Math.sin((m2-md)*0.3-t*1.5)*0.15;
  };
  const blend=coupled*0.6+cell*0.15+voronoi()*0.25;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,55],[10,45,95],[15,85,125],[25,135,140],[55,170,120],
    [130,190,80],[200,195,55],[220,150,50],[210,100,60],[180,60,70],
    [130,35,75],[70,20,60],[30,12,50],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.75+Math.sin(coupled*Math.PI)*0.25;
  const edge=Math.abs(coupled)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(coupled)*2)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*50)|0)
  ];
}
